var pack = JSON.parse(JSON.stringify($('Store Pack In Supabase').first().json));

function safe(value, fallback) {
  return value === undefined || value === null || value === '' ? (fallback || '') : String(value);
}

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

var baseUrl = 'https://n8n-pxlk.srv1480638.hstgr.cloud';
var approveUrl = baseUrl + '/webhook/approve-prospect-pack-v3?pack_id=' + encodeURIComponent(pack.pack_id) + '&decision=approved';
var rejectUrl = baseUrl + '/webhook/approve-prospect-pack-v3?pack_id=' + encodeURIComponent(pack.pack_id) + '&decision=rejected';
var subjectPreview = "Proposition d'audit gratuit, d'accompagnement et de formation";
var attachmentCount = pack.payload && Array.isArray(pack.payload.mail_attachments) ? pack.payload.mail_attachments.length : 0;
var auditFormUrl = safe((pack.payload && pack.payload.audit_form_url) || pack.audit_form_url, 'a confirmer');
var summary = [
  'Organisation: ' + escapeHtml(safe(pack.organization_name, 'a confirmer')),
  'Email cible: ' + escapeHtml(safe(pack.target_email, 'a confirmer')),
  "Cas d'usage: " + escapeHtml(safe((pack.payload && (pack.payload.best_selling_use_case || pack.payload.recommended_use_case)) || '', 'a confirmer')),
  'Offre recommandee: ' + escapeHtml(safe(pack.payload && pack.payload.recommended_offer, 'a confirmer')),
  'Tier: ' + escapeHtml(safe(pack.payload && pack.payload.commercial_priority_tier, 'n/a')),
  'Lien formulaire: ' + escapeHtml(auditFormUrl),
  'CTA: ' + escapeHtml(safe(pack.payload && pack.payload.single_primary_cta, 'a confirmer')),
  'Pack ID: ' + escapeHtml(safe(pack.pack_id, 'n/a')),
  'Pieces jointes preparees: ' + escapeHtml(String(attachmentCount)),
  'Sujet prevu: ' + escapeHtml(subjectPreview)
].join('<br>');
return [{
  json: Object.assign({}, pack, {
    approve_url: approveUrl,
    reject_url: rejectUrl,
    subject_preview: subjectPreview,
    internal_review_html:
      '<p>Un nouveau prospect pack est pret a valider.</p>' +
      '<p>' + summary + '</p>' +
      '<p><a href="' + approveUrl + '" style="color:green;font-weight:bold">Approuver et envoyer</a></p>' +
      '<p><a href="' + rejectUrl + '" style="color:red;font-weight:bold">Rejeter</a></p>'
  })
}];

